import { useEffect, useMemo, useState } from 'react';

import { InternalSliceData } from '../types/internal/pie-chart.js';

type PieState = {
  slices: InternalSliceData[];
  slicesMap: Map<string, InternalSliceData>;
  updateSlices: (prev: React.SetStateAction<InternalSliceData[]>) => void;
};

/**
 * Hook that setups all of the required states for the Pie
 * @param data - Initial data coming to the Pie
 * @param height - Initial height for the Pie
 * @param initialLegend - Initial legend config
 * @returns Object containing all of the Pie states
 */
export function usePieState(data: InternalSliceData[]): PieState {
  const [slices, setSlices] = useState<InternalSliceData[]>([]);

  const slicesMap = useMemo(() => {
    const sliceMap = new Map<string, InternalSliceData>();

    data.forEach((slice) => {
      sliceMap.set(slice.id, slice);
    });

    return sliceMap;
  }, [data]);

  useEffect(() => {
    setSlices(data.map((d) => ({ ...d, highlighted: true })));
  }, [data]);

  return {
    slices,
    slicesMap,
    updateSlices: setSlices,
  };
}
